referenceSolutions.python:
def islandLedgersFirstQualifyingSlip(links, k):
    a=links
    out=[]
    n=len(a)
    seen=[False]*n
    for start in range(n):
        if seen[start]: continue
        stack=[start]
        seen[start]=True
        count=0
        while stack:
            u=stack.pop()
            count+=1
            for v in range(n):
                if a[u][v] and not seen[v]:
                    seen[v]=True
                    stack.append(v)
        out.append(count)
    return next((x for x in out if x>=k),-1)

